<?php require '../config/database.php';auth();$customers=$pdo->query('SELECT id,name FROM customers ORDER BY name')->fetchAll();$repairs=$pdo->query("SELECT r.id,r.final_cost,r.paid_amount,c.name FROM repairs r JOIN customers c ON c.id=r.customer_id WHERE r.final_cost>r.paid_amount ORDER BY r.id DESC")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$amount=(float)$_POST['amount'];$rid=$_POST['repair_id']?:null;$cid=$_POST['customer_id']?:null;$s=$pdo->prepare('INSERT INTO payments(customer_id,repair_id,amount,payment_method,notes) VALUES(?,?,?,?,?)');$s->execute([$cid,$rid,$amount,$_POST['payment_method'],$_POST['notes']]);if($rid){$u=$pdo->prepare('UPDATE repairs SET paid_amount=paid_amount+? WHERE id=?');$u->execute([$amount,$rid]);}header('Location:index.php');exit;}?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><main><h1>تسجيل دفعة</h1><form method="post"><label>العميل</label><select name="customer_id"><option value="">غير محدد</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select><label>طلب الصيانة</label><select name="repair_id"><option value="">بدون</option><?php foreach($repairs as $r):?><option value="<?=$r['id']?>">#<?=$r['id']?> - <?=htmlspecialchars($r['name'])?> - متبقي <?=$r['final_cost']-$r['paid_amount']?></option><?php endforeach;?></select><label>المبلغ</label><input type="number" step="0.01" name="amount" required><label>طريقة الدفع</label><select name="payment_method"><option value="cash">نقدي</option><option value="transfer">تحويل</option><option value="card">بطاقة</option></select><label>ملاحظات</label><textarea name="notes"></textarea><button>حفظ الدفعة</button></form></main>
